  var EXTRA = {};

  /* ---------- social marks (Simple Icons, CC0). variant: tile | color | mono ---------- */
  function social(name, o) {
    o = o || {};
    var s = SOCIAL[name]; if (!s) return '';
    var v = o.variant || 'tile', z = o.size || 40, t = esc(s.t);
    if (v === 'tile') return '<svg class="bd-social bd-social--tile" width="' + z + '" height="' + z + '" viewBox="0 0 512 512" role="img" aria-label="' + t + '"><rect width="512" height="512" rx="116" fill="#' + s.h + '"/><g transform="translate(88 88) scale(14)"><path fill="' + (name === 'snapchat' ? '#000' : '#fff') + '" d="' + s.d + '"/></g></svg>';
    var fill = v === 'mono' ? 'currentColor' : (/^(0{6}|181717|525252)$/i.test(s.h) ? 'var(--text-primary)' : '#' + s.h);
    return '<svg class="bd-social bd-social--' + v + '" width="' + z + '" height="' + z + '" viewBox="0 0 24 24" role="img" aria-label="' + t + '"><path fill="' + fill + '" d="' + s.d + '"/></svg>';
  }
  function SocialButton(o) {
    o = o || {};
    return '<button type="button" class="bd-btn bd-btn--secondary bd-btn--lg bd-btn--block bd-socialbtn">' + social(o.social, { size: 24 }) + '<span>' + esc(o.label || ('Continue with ' + (SOCIAL[o.social] || {}).t)) + '</span></button>';
  }
  function ShareRow(o) {
    o = o || {};
    return '<div class="bd-share">' + (o.items || ['telegram', 'whatsapp', 'instagram', 'x', 'vk', 'max']).map(function (n) { return '<button type="button" class="bd-share__item">' + social(n, { size: 52 }) + '<span>' + esc((SOCIAL[n] || {}).t || n) + '</span></button>'; }).join('') + '</div>';
  }
