  function fmtRub(n) { return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + ' ₽'; }
  function svcPrice(x) { return x.p ? (x.from ? 'от ' : '') + fmtRub(x.p) : 'Бесплатно'; }
  function svcRange(key) {
    var l = SVC[key] || [], paid = l.filter(function (x) { return x.p; }), min = paid.length ? Math.min.apply(null, paid.map(function (x) { return x.p; })) : 0;
    return { n: l.length, free: l.filter(function (x) { return !x.p; }).length, min: min, allFree: l.length > 0 && !paid.length };
  }
