      if (s.published) items.unshift({ id: 'own-case', kind: 'found', icon: 'briefcase', title: 'Ваш случай опубликован', body: caseStatus() + '. Откройте карточку и проверьте следующий шаг.', time: 'Сейчас', target: 'case:route' });
