      if (s.taskAccepted) items.unshift({ id: 'helper-accepted', kind: 'help', icon: 'check', title: s.role === 'volunteer' ? 'Вы приняли задачу' : 'Помощник взял задачу', body: 'Проверьте следующее действие и статус передачи в случае.', time: 'Сейчас', target: 'case:history' });
