      if (s.noResponse) items.unshift({ id: 'no-response', kind: 'help', icon: 'share', title: 'Можно расширить поиск помощи', body: 'Подготовьте листовку для районного сообщества.', time: 'Сейчас', target: 'share' });
      if (s.caseClosed) items.unshift({ id: 'case-outcome', kind: 'found', icon: 'check', title: 'У случая появился итог', body: OUTCOMES[s.outcome] || 'Итог записан в маршруте помощи.', time: 'Сейчас', target: 'case:history' });
