      var pins = [['n1', 28, 38], ['n2', 72, 28], ['n3', 75, 65], ['n4', 23, 63], ['n5', 47, 80], ['n6', 58, 15], ['n7', 12, 18], ['n8', 38, 52], ['n9', 84, 44], ['n10', 62, 40]].filter(function (p) { return ids ? ids.indexOf(p[0]) >= 0 : inRadius(byId(CASES, p[0])); });
