      var earned = list.filter(function (m) { return pm.have[m.id]; }), ways = list.filter(function (m) { return !pm.have[m.id] && !m.limited; }), lim = list.filter(function (m) { return m.limited; });
      var toast = B.MedalToast({ medals: earned.slice(0, 3).map(function (m) { return mArgs(m); }), title: 'Получено ' + earned.length + ' из ' + list.length, sub: 'Награды платформы «Подхват»' });
