      return btn('', 'close-medal', 'pd-scrim', 'aria-label="Закрыть"') + '<div class="pd-sheet pd-msheet bd-glass bd-glass--strong" role="dialog" aria-label="Награда: ' + esc(m.name) + '"><div class="pd-sheet__grip"></div><div class="pd-msheet__medal">' + B.Medal(mArgs(m, got ? { size: 128, shine: true, pop: true } : { size: 128, locked: true })) + '</div>' +
        '<div class="pd-msheet__txt">' + (m.limited ? '<span class="bd-badge bd-badge--yellow bd-badge--sm">Лимитированная</span>' : '') + '<h3 class="title-lg">' + esc(m.name) + '</h3><p class="body-lg">' + m.desc + '</p></div>' + status + (got ? '' : '<div class="pd-note">' + ico('info', 20) + '<span>' + m.how + '</span></div>') + btn('Понятно', 'close-medal', blk(BM + ' bd-btn--lg')) + '</div>';
