    function badgeRow(tags, stack) { return '<div class="pd-badges' + (stack ? ' pd-badges--stack' : '') + '">' + tags.map(function (k) { var t = TAGS[k]; return '<span class="pd-badge pd-badge--' + t[2] + '" role="img" aria-label="' + t[1] + '" title="' + t[1] + '">' + glyph(TAG_EMO[k], 24) + '</span>'; }).join('') + '</div>'; }
    function featGrid(tags) { return '<div class="pd-feats">' + tags.filter(function (k) { return k !== 'top'; }).map(function (k) { var t = TAGS[k]; return '<span class="pd-feat"><span class="pd-badge pd-badge--' + t[2] + '">' + glyph(TAG_EMO[k], 24) + '</span><b>' + t[1] + '</b></span>'; }).join('') + '</div>'; }
    function stars(r) { return '<span class="pd-rate" aria-label="Рейтинг ' + r + '">' + ico('star', 16) + '<b>' + r + '</b></span>'; }
    var SP_NAME = { 'sp-cat': 'Кошки', 'sp-dog': 'Собаки', 'sp-rabbit': 'Кролики', 'sp-bird': 'Птицы', 'sp-turtle': 'Рептилии', 'sp-fox': 'Лисы', 'sp-hedgehog': 'Ежи', 'sp-owl': 'Совы', 'sp-hamster': 'Хомяки', 'sp-guinea': 'Морские свинки', 'sp-rat': 'Крысы', 'sp-ferret': 'Хорьки', 'sp-parrot': 'Попугаи', 'sp-canary': 'Канарейки', 'sp-pigeon': 'Голуби', 'sp-lizard': 'Ящерицы', 'sp-snake': 'Змеи', 'sp-frog': 'Лягушки', 'sp-horse': 'Лошади', 'sp-goat': 'Козы', 'sp-sheep': 'Овцы', 'sp-cow': 'Коровы' };
    function acceptsBlock(o, m) {
      if (!m.accepts.length) return '<section class="pd-card pd-card--tint pd-acc"><div class="pd-mini"><strong>Что здесь есть</strong>' + tag('Для передержки', 'pink') + '</div><div class="pd-chips">' + o.services.split(', ').map(function (x) { return '<span class="pd-trait">' + ico('check', 16, 3) + esc(x) + '</span>'; }).join('') + '</div><p class="pd-sub">Животных магазин не принимает: он помогает с товарами для временной передержки.</p></section>';
      var no = Object.keys(SP_NAME).filter(function (k) { return m.accepts.indexOf(k) < 0 && ['sp-cat', 'sp-dog', 'sp-rabbit', 'sp-hamster', 'sp-parrot', 'sp-bird', 'sp-turtle', 'sp-lizard'].indexOf(k) >= 0; });
      return '<section class="pd-card pd-card--tint pd-acc"><div class="pd-mini"><strong>Принимают</strong><span class="pd-save">' + m.accepts.length + ' ' + (m.accepts.length > 4 ? 'видов' : 'вида') + '</span></div><div class="pd-acc__g">' + m.accepts.map(function (n) { return '<span class="pd-acc__i">' + B.species(n, { size: 44 }) + '<b>' + SP_NAME[n] + '</b><small>' + ico('check', 12, 3) + ' принимают</small></span>'; }).join('') + '</div>' +
        (no.length ? '<p class="pd-acc__no">' + ico('info', 16) + '<span>Не принимают: ' + no.map(function (k) { return SP_NAME[k].toLowerCase(); }).join(', ') + '</span></p>' : '') + '<p class="pd-acc__no">' + ico('clock', 16) + '<span>Приём по согласованию: сначала отправьте данные случая, место подтвердят отдельно.</span></p></section>';
    }
    var PIMG = { 'org:clinic': ['cat', '50% 35%'], 'org:shelter': ['dog', '50% 35%'], 'org:wild': ['rabbit', '50% 55%'], 'org:farm': ['goat', '50% 40%'],
      'vol:maria': ['dog', '30% 40%'], 'vol:ilya': ['goat', '65% 40%'], 'vol:lida': ['catMatch', '50% 30%'], 'vol:dmitry': ['cat', '50% 25%'], 'vol:olga': ['rabbit', '65% 50%'], 'vol:anna': ['catMatch', '30% 40%'], 'vol:timur': ['dog', '70% 50%'], 'vol:elena': ['rabbit', '30% 60%'], 'vol:sergey': ['dog', '50% 20%'] };
    function pimg(key, size, round, fallback, cls, zoom) {
      var d = PIMG[key], src = d && photos[d[0]]; if (!src) return fallback;
      return '<span' + (zoom ? ' data-zoom="' + key + '" data-zi="0" role="button" tabindex="0" aria-label="Открыть фото"' : '') + ' class="pd-pimg' + (zoom ? ' pd-zoomable' : '') + (round ? ' pd-pimg--round' : '') + (cls ? ' ' + cls : '') + '" style="--sz:' + size + 'px"><img src="' + src + '" alt="" style="object-position:' + d[1] + '"></span>';
    }
